#!/usr/bin/env bash

bp_render_config() { mkdir -p "$TARGET_DIR/.ddev"; cat > "$TARGET_DIR/.ddev/config.yaml" <<EOF
# Generated by ddev-blueprint. Review before committing.
name: $PROJECT_NAME
type: php
docroot: $DOCROOT
php_version: "$PHP_VERSION"
webserver_type: $WEBSERVER
EOF
if [[ "$DB_TYPE" == none ]]; then printf '\nomit_containers:\n  - db\n' >> "$TARGET_DIR/.ddev/config.yaml"; else printf '\ndatabase:\n  type: %s\n  version: "%s"\n' "$DB_TYPE" "$DB_VERSION" >> "$TARGET_DIR/.ddev/config.yaml"; [[ -n "$HOST_DB_PORT" ]] && printf '\nhost_db_port: "%s"\n' "$HOST_DB_PORT" >> "$TARGET_DIR/.ddev/config.yaml"; fi; if (( ${#HOSTNAMES[@]} )); then printf '\nadditional_hostnames:\n' >> "$TARGET_DIR/.ddev/config.yaml"; printf '  - "%s"\n' "${HOSTNAMES[@]}" >> "$TARGET_DIR/.ddev/config.yaml"; fi; if (( ${#FQDNS[@]} )); then printf '\nadditional_fqdns:\n' >> "$TARGET_DIR/.ddev/config.yaml"; printf '  - "%s"\n' "${FQDNS[@]}" >> "$TARGET_DIR/.ddev/config.yaml"; fi; if (( ${#PACKAGES[@]} )); then printf '\nwebimage_extra_packages:\n' >> "$TARGET_DIR/.ddev/config.yaml"; printf '  - %s\n' "${PACKAGES[@]}" >> "$TARGET_DIR/.ddev/config.yaml"; fi; printf '\nweb_environment:\n  - APP_ENV=development\n' >> "$TARGET_DIR/.ddev/config.yaml"; }
bp_render_services() { if [[ "$ENABLE_PHP_SETTINGS" == y ]]; then mkdir -p "$TARGET_DIR/.ddev/php"; cp "$SCRIPT_DIR/templates/99-development.ini" "$TARGET_DIR/.ddev/php/99-development.ini"; fi; if [[ "$ENABLE_REDIS_SERVICE" == y ]]; then cat > "$TARGET_DIR/.ddev/docker-compose.redis.yaml" <<EOF
services:
  redis:
    container_name: "ddev-\${DDEV_SITENAME}-redis"
    image: "redis:$REDIS_TAG"
    restart: "no"
    expose: ["6379"]
EOF
fi; if [[ "$ENABLE_OTEL" == y ]]; then mkdir -p "$TARGET_DIR/.ddev/otel"; cat > "$TARGET_DIR/.ddev/docker-compose.otel.yaml" <<EOF
services:
  otel-collector:
    container_name: "ddev-\${DDEV_SITENAME}-otel-collector"
    image: "otel/opentelemetry-collector-contrib:$DEFAULT_OTEL_VERSION"
    restart: "no"
    command: ["--config=/etc/otelcol-contrib/config.yaml"]
    expose: ["4317", "4318"]
    volumes: ["./otel/collector-config.yaml:/etc/otelcol-contrib/config.yaml:ro"]
EOF
cp "$SCRIPT_DIR/templates/otel-collector-config.yaml" "$TARGET_DIR/.ddev/otel/collector-config.yaml"; fi; return 0; }
bp_render_makefile() { [[ "$ENABLE_MAKEFILE" == y && ! -e "$TARGET_DIR/Makefile" ]] || return 0; MAKE_TARGETS=(help start stop restart status shell logs composer-install); MAKE_DESCRIPTIONS=('Show available targets' 'Start the DDEV project' 'Stop the DDEV project' 'Restart the DDEV project' 'Show DDEV project status' 'Open a shell in the web container' 'Follow DDEV logs' 'Install Composer dependencies'); [[ -e "$TARGET_DIR/vendor/bin/phpstan" ]] && { MAKE_TARGETS+=(phpstan); MAKE_DESCRIPTIONS+=('Run PHPStan'); }; [[ -e "$TARGET_DIR/vendor/bin/phpcs" ]] && { MAKE_TARGETS+=(phpcs); MAKE_DESCRIPTIONS+=('Run PHP_CodeSniffer'); }; [[ -e "$TARGET_DIR/phpunit.xml" || -e "$TARGET_DIR/phpunit.xml.dist" ]] && { MAKE_TARGETS+=(test); MAKE_DESCRIPTIONS+=('Run PHPUnit'); }; [[ -e "$TARGET_DIR/bin/console" ]] && { MAKE_TARGETS+=(console); MAKE_DESCRIPTIONS+=('Run the Symfony console'); }; [[ -e "$TARGET_DIR/artisan" ]] && { MAKE_TARGETS+=(artisan); MAKE_DESCRIPTIONS+=('Run Laravel Artisan'); }; if [[ -e "$TARGET_DIR/package.json" ]]; then MAKE_TARGETS+=(npm-install); MAKE_DESCRIPTIONS+=('Install npm dependencies'); if command -v jq >/dev/null 2>&1 && jq -e '.scripts.build? != null' "$TARGET_DIR/package.json" >/dev/null 2>&1; then MAKE_TARGETS+=(npm-build); MAKE_DESCRIPTIONS+=('Build frontend assets'); elif ! command -v jq >/dev/null 2>&1; then bp_add_skipped 'npm-build (jq unavailable)'; fi; fi; { printf '.PHONY: %s\n\n' "${MAKE_TARGETS[*]}"; printf 'help:\n\t@printf '\''Available targets:\\n'\''\n'; local index; for index in "${!MAKE_TARGETS[@]}"; do printf "\t@printf '  %%-18s %%s\\\\n' '%s' '%s'\n" "${MAKE_TARGETS[$index]}" "${MAKE_DESCRIPTIONS[$index]}"; done; printf '\nstart:\n\tddev start\n\nstop:\n\tddev stop\n\nrestart:\n\tddev restart\n\nstatus:\n\tddev describe\n\nshell:\n\tddev ssh\n\nlogs:\n\tddev logs -f\n\ncomposer-install:\n\tddev composer install\n'; [[ -e "$TARGET_DIR/vendor/bin/phpstan" ]] && printf '\nphpstan:\n\tddev exec -- vendor/bin/phpstan\n'; [[ -e "$TARGET_DIR/vendor/bin/phpcs" ]] && printf '\nphpcs:\n\tddev exec -- vendor/bin/phpcs\n'; [[ -e "$TARGET_DIR/phpunit.xml" || -e "$TARGET_DIR/phpunit.xml.dist" ]] && printf '\ntest:\n\tddev exec -- vendor/bin/phpunit\n'; [[ -e "$TARGET_DIR/bin/console" ]] && printf '\nconsole:\n\tddev exec -- bin/console\n'; [[ -e "$TARGET_DIR/artisan" ]] && printf '\nartisan:\n\tddev exec -- php artisan\n'; if [[ -e "$TARGET_DIR/package.json" ]]; then printf '\nnpm-install:\n\tddev exec -- npm install\n'; [[ " ${MAKE_TARGETS[*]} " == *' npm-build '* ]] && printf '\nnpm-build:\n\tddev exec -- npm run build\n'; fi; } > "$TARGET_DIR/Makefile"; }
bp_render_optional_files() { if [[ "$ENABLE_EDITORCONFIG" == y && ! -e "$TARGET_DIR/.editorconfig" ]]; then cp "$SCRIPT_DIR/templates/editorconfig" "$TARGET_DIR/.editorconfig"; fi; if [[ "$ENABLE_ENV_TEMPLATE" == y && ! -e "$TARGET_DIR/.env.local.example" ]]; then printf '# Example local environment values.\nAPP_ENV=development\n' > "$TARGET_DIR/.env.local.example"; [[ "$DB_TYPE" == none ]] || printf '\nDB_HOST=db\nDB_PORT=%s\nDB_NAME=db\nDB_USER=db\nDB_PASSWORD=db\n' "$([[ "$DB_TYPE" == postgres ]] && printf 5432 || printf 3306)" >> "$TARGET_DIR/.env.local.example"; [[ "$ENABLE_REDIS_SERVICE" == y ]] && printf '\nREDIS_HOST=redis\nREDIS_PORT=6379\n' >> "$TARGET_DIR/.env.local.example" || true; [[ "$ENABLE_OTEL" == y ]] && printf '\nOTEL_EXPORTER_OTLP_ENDPOINT=http://otel-collector:4318\n' >> "$TARGET_DIR/.env.local.example" || true; fi; return 0; }
bp_render_project() { mkdir -p "$TARGET_DIR"; bp_render_config; bp_render_services; bp_render_makefile; bp_render_optional_files; return 0; }
